WITH RECURSIVE commodity AS (  SELECT gn.goods_nomenclature_sid,         gn.goods_nomenclature_item_id,         gn.producline_suffix,         to_char(gn.validity_start_date, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS validity_start_date,         CASE WHEN gn.validity_end_date IS NULL THEN NULL ELSE to_char(gn.validity_end_date, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END AS validity_end_date,         d.description,         d.consigned_from,         i.number_indents,         node.position AS node_position,         node.depth AS node_depth,         NOT EXISTS (           SELECT 1 FROM {{SCHEMA}}.goods_nomenclature_tree_nodes child           WHERE child.position > node.position             AND child.position < COALESCE((               SELECT sibling.position               FROM {{SCHEMA}}.goods_nomenclature_tree_nodes sibling               WHERE sibling.position > node.position                 AND sibling.depth <= node.depth                 AND sibling.validity_start_date <= {{ACTUAL_DATE}}                 AND (sibling.validity_end_date IS NULL OR sibling.validity_end_date >= {{ACTUAL_DATE}})               ORDER BY sibling.position               LIMIT 1             ), 999999999999::bigint)             AND child.validity_start_date <= {{ACTUAL_DATE}}             AND (child.validity_end_date IS NULL OR child.validity_end_date >= {{ACTUAL_DATE}})         ) AS leaf,         EXISTS (SELECT 1 FROM {{SCHEMA}}.full_chemicals fc WHERE fc.goods_nomenclature_sid = gn.goods_nomenclature_sid) AS has_chemicals  FROM {{SCHEMA}}.goods_nomenclatures gn  JOIN {{SCHEMA}}.goods_nomenclature_tree_nodes node ON node.goods_nomenclature_sid = gn.goods_nomenclature_sid  LEFT JOIN LATERAL (    SELECT description,           NULLIF(trim((regexp_match(description, 'consigned from(?: or originating in)?([[:alpha:],''[:space:]]+)(?:[^[:alpha:]]|$)', 'i'))[1]), '') AS consigned_from    FROM {{SCHEMA}}.goods_nomenclature_description_periods p    JOIN {{SCHEMA}}.goods_nomenclature_descriptions gd      ON gd.goods_nomenclature_description_period_sid = p.goods_nomenclature_description_period_sid     AND gd.goods_nomenclature_sid = p.goods_nomenclature_sid    WHERE p.goods_nomenclature_sid = gn.goods_nomenclature_sid      AND p.validity_start_date <= {{ACTUAL_DATE}}      AND (p.validity_end_date IS NULL OR p.validity_end_date >= {{ACTUAL_DATE}})      AND gd.description IS NOT NULL    ORDER BY p.validity_start_date DESC    LIMIT 1  ) d ON true  LEFT JOIN LATERAL (    SELECT number_indents    FROM {{SCHEMA}}.goods_nomenclature_indents gi    WHERE gi.goods_nomenclature_sid = gn.goods_nomenclature_sid      AND gi.validity_start_date <= {{ACTUAL_DATE}}      AND (gi.validity_end_date IS NULL OR gi.validity_end_date >= {{ACTUAL_DATE}})    ORDER BY gi.validity_start_date DESC    LIMIT 1  ) i ON true  WHERE gn.goods_nomenclature_item_id = $1    AND gn.producline_suffix = '80'    AND gn.validity_start_date <= {{ACTUAL_DATE}}    AND (gn.validity_end_date IS NULL OR gn.validity_end_date >= {{ACTUAL_DATE}})    AND node.validity_start_date <= {{ACTUAL_DATE}}    AND (node.validity_end_date IS NULL OR node.validity_end_date >= {{ACTUAL_DATE}})    AND NOT EXISTS (SELECT 1 FROM {{SCHEMA}}.hidden_goods_nomenclatures h WHERE h.goods_nomenclature_item_id = gn.goods_nomenclature_item_id)  ORDER BY gn.goods_nomenclature_sid DESC  LIMIT 1),chapter_resource AS (  SELECT jsonb_build_object(    'id', ch.goods_nomenclature_sid::text,    'type', 'chapter',    'attributes', jsonb_build_object(      'goods_nomenclature_item_id', ch.goods_nomenclature_item_id,      'description', cd.description,      'formatted_description', CASE WHEN cd.description IS NULL OR cd.description = '' THEN '' ELSE regexp_replace(regexp_replace(replace(upper(substr(lower(cd.description), 1, 1)) || substr(lower(cd.description), 2), chr(160), ' '), '(\d),(\d)', '\1.\2', 'g'), '(\d)\s+%', '\1%', 'g') END,      'validity_start_date', to_char(ch.validity_start_date, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),      'validity_end_date', CASE WHEN ch.validity_end_date IS NULL THEN NULL ELSE to_char(ch.validity_end_date, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,      'chapter_note', cn.content    ),    'relationships', jsonb_build_object('guides', jsonb_build_object('data', jsonb_build_array()))  ) AS resource,  jsonb_build_object('id', ch.goods_nomenclature_sid::text, 'type', 'chapter') AS ref  FROM commodity  JOIN {{SCHEMA}}.goods_nomenclatures ch ON ch.goods_nomenclature_item_id = substring(commodity.goods_nomenclature_item_id, 1, 2) || '00000000'  LEFT JOIN LATERAL (    SELECT gd.description    FROM {{SCHEMA}}.goods_nomenclature_description_periods p    JOIN {{SCHEMA}}.goods_nomenclature_descriptions gd ON gd.goods_nomenclature_description_period_sid = p.goods_nomenclature_description_period_sid AND gd.goods_nomenclature_sid = p.goods_nomenclature_sid    WHERE p.goods_nomenclature_sid = ch.goods_nomenclature_sid AND p.validity_start_date <= {{ACTUAL_DATE}} AND (p.validity_end_date IS NULL OR p.validity_end_date >= {{ACTUAL_DATE}})    ORDER BY p.validity_start_date DESC LIMIT 1  ) cd ON true  LEFT JOIN {{SCHEMA}}.chapter_notes cn ON cn.chapter_id = substring(commodity.goods_nomenclature_item_id, 1, 2)  LIMIT 1),heading_resource AS (  SELECT jsonb_build_object(    'id', hd.goods_nomenclature_sid::text,    'type', 'heading',    'attributes', jsonb_build_object(      'goods_nomenclature_item_id', hd.goods_nomenclature_item_id,      'description', hd_desc.description,      'formatted_description', CASE WHEN hd_desc.description IS NULL OR hd_desc.description = '' THEN '' ELSE regexp_replace(regexp_replace(replace(upper(substr(lower(hd_desc.description), 1, 1)) || substr(lower(hd_desc.description), 2), chr(160), ' '), '(\d),(\d)', '\1.\2', 'g'), '(\d)\s+%', '\1%', 'g') END,      'description_plain', CASE WHEN hd_desc.description IS NULL OR hd_desc.description = '' THEN '' ELSE upper(substr(lower(hd_desc.description), 1, 1)) || substr(lower(hd_desc.description), 2) END,      'validity_start_date', to_char(hd.validity_start_date, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),      'validity_end_date', CASE WHEN hd.validity_end_date IS NULL THEN NULL ELSE to_char(hd.validity_end_date, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END    )  ) AS resource,  jsonb_build_object('id', hd.goods_nomenclature_sid::text, 'type', 'heading') AS ref,  hd.goods_nomenclature_sid AS sid  FROM commodity  JOIN {{SCHEMA}}.goods_nomenclatures hd ON hd.goods_nomenclature_item_id = substring(commodity.goods_nomenclature_item_id, 1, 4) || '000000' AND hd.producline_suffix = '80'    AND hd.validity_start_date <= {{ACTUAL_DATE}}    AND (hd.validity_end_date IS NULL OR hd.validity_end_date >= {{ACTUAL_DATE}})  LEFT JOIN LATERAL (    SELECT gd.description    FROM {{SCHEMA}}.goods_nomenclature_description_periods p    JOIN {{SCHEMA}}.goods_nomenclature_descriptions gd ON gd.goods_nomenclature_description_period_sid = p.goods_nomenclature_description_period_sid AND gd.goods_nomenclature_sid = p.goods_nomenclature_sid    WHERE p.goods_nomenclature_sid = hd.goods_nomenclature_sid AND p.validity_start_date <= {{ACTUAL_DATE}} AND (p.validity_end_date IS NULL OR p.validity_end_date >= {{ACTUAL_DATE}})    ORDER BY p.validity_start_date DESC LIMIT 1  ) hd_desc ON true  LIMIT 1),section_resource AS (  SELECT jsonb_build_object(    'id', s.id::text,    'type', 'section',    'attributes', jsonb_strip_nulls(jsonb_build_object('numeral', s.numeral, 'title', s.title, 'position', s.position, 'section_note', sn.content))  ) AS resource,  jsonb_build_object('id', s.id::text, 'type', 'section') AS ref  FROM commodity  JOIN {{SCHEMA}}.goods_nomenclatures ch ON ch.goods_nomenclature_item_id = substring(commodity.goods_nomenclature_item_id, 1, 2) || '00000000'  JOIN {{SCHEMA}}.chapters_sections cs ON cs.goods_nomenclature_sid = ch.goods_nomenclature_sid  JOIN {{SCHEMA}}.sections s ON s.id = cs.section_id  LEFT JOIN {{SCHEMA}}.section_notes sn ON sn.section_id = s.id  LIMIT 1),ancestor_resources AS (  SELECT jsonb_build_object(    'id', nearest.goods_nomenclature_sid::text,    'type', 'commodity',    'attributes', jsonb_build_object(      'producline_suffix', nearest.productline_suffix,      'description', ad.description,      'number_indents', ai.number_indents,      'goods_nomenclature_item_id', nearest.goods_nomenclature_item_id,      'formatted_description', CASE WHEN ad.description IS NULL OR ad.description = '' THEN '' ELSE regexp_replace(regexp_replace(replace(upper(substr(lower(ad.description), 1, 1)) || substr(lower(ad.description), 2), chr(160), ' '), '(\d),(\d)', '\1.\2', 'g'), '(\d)\s+%', '\1%', 'g') END,      'description_plain', CASE WHEN ad.description IS NULL OR ad.description = '' THEN '' ELSE upper(substr(lower(ad.description), 1, 1)) || substr(lower(ad.description), 2) END,      'validity_start_date', to_char(agn.validity_start_date, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),      'validity_end_date', CASE WHEN agn.validity_end_date IS NULL THEN NULL ELSE to_char(agn.validity_end_date, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END    )  ) AS resource,  jsonb_build_object('id', nearest.goods_nomenclature_sid::text, 'type', 'commodity') AS ref,  nearest.position  FROM commodity  JOIN (    SELECT * FROM (      SELECT DISTINCT ON (n.depth) n.goods_nomenclature_sid, n.goods_nomenclature_item_id, n.productline_suffix, n.position      FROM {{SCHEMA}}.goods_nomenclature_tree_nodes n, commodity      WHERE n.position < commodity.node_position        AND n.position >= ((substring(commodity.goods_nomenclature_item_id, 1, 2) || '0000000080')::bigint)        AND n.depth < commodity.node_depth        AND n.validity_start_date <= {{ACTUAL_DATE}}        AND (n.validity_end_date IS NULL OR n.validity_end_date >= {{ACTUAL_DATE}})      ORDER BY n.depth, n.position DESC    ) nearest_depth    WHERE nearest_depth.goods_nomenclature_item_id NOT LIKE '__00000000'      AND nearest_depth.goods_nomenclature_item_id NOT LIKE '____000000'  ) nearest ON true  JOIN {{SCHEMA}}.goods_nomenclatures agn ON agn.goods_nomenclature_sid = nearest.goods_nomenclature_sid  LEFT JOIN LATERAL (    SELECT gd.description    FROM {{SCHEMA}}.goods_nomenclature_description_periods p    JOIN {{SCHEMA}}.goods_nomenclature_descriptions gd ON gd.goods_nomenclature_description_period_sid = p.goods_nomenclature_description_period_sid AND gd.goods_nomenclature_sid = p.goods_nomenclature_sid    WHERE p.goods_nomenclature_sid = nearest.goods_nomenclature_sid AND p.validity_start_date <= {{ACTUAL_DATE}} AND (p.validity_end_date IS NULL OR p.validity_end_date >= {{ACTUAL_DATE}})    ORDER BY p.validity_start_date DESC LIMIT 1  ) ad ON true  LEFT JOIN LATERAL (    SELECT gi.number_indents    FROM {{SCHEMA}}.goods_nomenclature_indents gi    WHERE gi.goods_nomenclature_sid = nearest.goods_nomenclature_sid AND gi.validity_start_date <= {{ACTUAL_DATE}} AND (gi.validity_end_date IS NULL OR gi.validity_end_date >= {{ACTUAL_DATE}})    ORDER BY gi.validity_start_date DESC LIMIT 1  ) ai ON true),footnote_rows AS (  SELECT f.footnote_type_id || f.footnote_id AS code, fd.description, p.validity_start_date,         CASE WHEN a.goods_nomenclature_sid = commodity.goods_nomenclature_sid THEN 0 ELSE 1 END AS source_group  FROM commodity  JOIN heading_resource hr ON true  JOIN {{SCHEMA}}.footnote_association_goods_nomenclatures a ON a.goods_nomenclature_sid IN (commodity.goods_nomenclature_sid, hr.sid)  JOIN LATERAL (    SELECT f.footnote_type_id, f.footnote_id    FROM {{SCHEMA}}.footnotes f    WHERE f.footnote_type_id = a.footnote_type AND f.footnote_id = a.footnote_id      AND f.validity_start_date <= {{ACTUAL_DATE}} AND (f.validity_end_date IS NULL OR f.validity_end_date >= {{ACTUAL_DATE}})    LIMIT 1  ) f ON true  JOIN LATERAL (    SELECT p.footnote_description_period_sid, p.footnote_type_id, p.footnote_id, p.validity_start_date    FROM {{SCHEMA}}.footnote_description_periods p    WHERE p.footnote_type_id = f.footnote_type_id AND p.footnote_id = f.footnote_id      AND p.validity_start_date <= {{ACTUAL_DATE}} AND (p.validity_end_date IS NULL OR p.validity_end_date >= {{ACTUAL_DATE}})    ORDER BY p.validity_start_date DESC    LIMIT 1  ) p ON true  JOIN LATERAL (    SELECT fd.description    FROM {{SCHEMA}}.footnote_descriptions fd    WHERE fd.footnote_description_period_sid = p.footnote_description_period_sid AND fd.footnote_type_id = p.footnote_type_id AND fd.footnote_id = p.footnote_id    LIMIT 1  ) fd ON true  WHERE a.validity_start_date <= {{ACTUAL_DATE}} AND (a.validity_end_date IS NULL OR a.validity_end_date >= {{ACTUAL_DATE}})),footnote_resources AS (  SELECT DISTINCT ON (code) jsonb_build_object(    'id', code,    'type', 'footnote',    'attributes', jsonb_build_object('code', code, 'description', description, 'formatted_description', description)  ) AS resource,  code  FROM footnote_rows  ORDER BY code, validity_start_date DESC),footnote_refs AS (  SELECT jsonb_build_object('id', code, 'type', 'footnote') AS ref, source_group, code  FROM footnote_rows),applicable_sids AS (  SELECT goods_nomenclature_sid AS sid FROM commodity  UNION  SELECT (ref->>'id')::integer FROM chapter_resource  UNION  SELECT (ref->>'id')::integer FROM heading_resource  UNION  SELECT (ref->>'id')::integer FROM ancestor_resources),deduped_measures AS (  SELECT DISTINCT ON (m.measure_generating_regulation_id, m.measure_generating_regulation_role, m.measure_type_id, m.goods_nomenclature_sid, m.geographical_area_id, m.geographical_area_sid, m.additional_code_type_id, m.additional_code_id, m.ordernumber)    m.measure_sid,    m.geographical_area_id,    m.geographical_area_sid,    m.measure_type_id,    m.additional_code_type_id,    m.additional_code_id,    m.additional_code_sid,    m.ordernumber,    m.reduction_indicator,    m.national,    mt.trade_movement_code,    mt.measure_type_series_id,    m.measure_generating_regulation_id,    m.measure_generating_regulation_role,    br.information_text AS base_information_text,    br.validity_start_date AS base_validity_start_date,    br.validity_end_date AS base_validity_end_date,    br.officialjournal_number AS base_officialjournal_number,    br.officialjournal_page AS base_officialjournal_page,    br.published_date AS base_published_date,    mr.information_text AS mod_information_text,    mr.validity_start_date AS mod_validity_start_date,    mr.validity_end_date AS mod_validity_end_date,    mr.officialjournal_number AS mod_officialjournal_number,    mr.officialjournal_page AS mod_officialjournal_page,    mr.published_date AS mod_published_date,    mr.base_regulation_id AS mod_base_regulation_id,    mr.base_regulation_role AS mod_base_regulation_role,    coalesce(m.validity_start_date, br.validity_start_date, mr.validity_start_date) AS effective_start_date,    coalesce(m.validity_end_date, br.effective_end_date, br.validity_end_date, mr.effective_end_date, mr.validity_end_date) AS effective_end_date  FROM {{SCHEMA}}.measures m  LEFT JOIN {{SCHEMA}}.base_regulations br ON br.base_regulation_id = m.measure_generating_regulation_id AND br.base_regulation_role = m.measure_generating_regulation_role AND br.approved_flag IS TRUE  LEFT JOIN {{SCHEMA}}.modification_regulations mr ON mr.modification_regulation_id = m.measure_generating_regulation_id AND mr.modification_regulation_role = m.measure_generating_regulation_role AND mr.approved_flag IS TRUE  JOIN LATERAL (    SELECT mt.trade_movement_code, mt.measure_type_series_id    FROM {{SCHEMA}}.measure_types mt    WHERE mt.measure_type_id = m.measure_type_id    LIMIT 1  ) mt ON true  WHERE m.goods_nomenclature_sid = ANY(ARRAY(SELECT sid FROM applicable_sids))    AND m.validity_start_date <= {{ACTUAL_DATE}}    AND (m.validity_end_date IS NULL OR m.validity_end_date >= {{ACTUAL_DATE}})    AND (br.base_regulation_id IS NOT NULL OR mr.modification_regulation_id IS NOT NULL)    AND coalesce(m.validity_start_date, br.validity_start_date, mr.validity_start_date) <= {{ACTUAL_DATE}}    AND (coalesce(m.validity_end_date, br.effective_end_date, br.validity_end_date, mr.effective_end_date, mr.validity_end_date) IS NULL OR coalesce(m.validity_end_date, br.effective_end_date, br.validity_end_date, mr.effective_end_date, mr.validity_end_date) >= {{ACTUAL_DATE}})    AND m.measure_type_id NOT IN ('442', '447', 'SPL')  ORDER BY m.measure_generating_regulation_id DESC, m.measure_generating_regulation_role DESC, m.measure_type_id DESC, m.goods_nomenclature_sid DESC, m.geographical_area_id DESC, m.geographical_area_sid DESC, m.additional_code_type_id DESC, m.additional_code_id DESC, m.ordernumber DESC, effective_start_date DESC),ordered_measures AS (  SELECT *, jsonb_build_object('id', measure_sid::text, 'type', 'measure') AS ref  FROM deduped_measures  ORDER BY geographical_area_id NULLS LAST, measure_type_id NULLS LAST, additional_code_type_id NULLS LAST, additional_code_id NULLS LAST, ordernumber NULLS LAST, effective_end_date NULLS LAST),measure_sequence AS (  SELECT measure_sid, row_number() OVER (ORDER BY movement_block, geographical_area_id NULLS LAST, measure_type_id NULLS LAST, additional_code_type_id NULLS LAST, additional_code_id NULLS LAST, ordernumber NULLS LAST, effective_end_date NULLS LAST) AS seq  FROM (    SELECT om.*, CASE WHEN trade_movement_code IN (0, 2) THEN 0 ELSE 1 END AS movement_block    FROM ordered_measures om  ) sequenced),measure_component_resources AS (  SELECT mc.measure_sid,    jsonb_build_object('id', mc.measure_sid::text || '-' || mc.duty_expression_id, 'type', 'measure_component') AS ref,    jsonb_build_object(      'id', mc.measure_sid::text || '-' || mc.duty_expression_id,      'type', 'measure_component',      'attributes', jsonb_build_object(        'duty_expression_id', mc.duty_expression_id,        'duty_amount', CASE WHEN mc.duty_amount = trunc(mc.duty_amount) THEN to_jsonb(mc.duty_amount::numeric(20,1)) ELSE to_jsonb(mc.duty_amount) END,        'monetary_unit_code', mc.monetary_unit_code,        'monetary_unit_abbreviation', CASE mc.monetary_unit_code WHEN 'EUC' THEN 'EUR (EUC)' ELSE NULL END,        'measurement_unit_code', mc.measurement_unit_code,        'measurement_unit_qualifier_code', mc.measurement_unit_qualifier_code,        'duty_expression_description', ded.description,        'duty_expression_abbreviation', NULL      ),      'relationships', CASE WHEN mc.measurement_unit_code IS NULL THEN jsonb_build_object() ELSE jsonb_build_object(        'measurement_unit', jsonb_build_object('data', jsonb_build_object('id', mc.measurement_unit_code, 'type', 'measurement_unit')),        'measurement_unit_qualifier', jsonb_build_object('data', CASE WHEN mc.measurement_unit_qualifier_code IS NULL THEN NULL ELSE jsonb_build_object('id', mc.measurement_unit_qualifier_code, 'type', 'measurement_unit_qualifier') END)      ) END    ) AS resource  FROM {{SCHEMA}}.measure_components mc  JOIN ordered_measures om ON om.measure_sid = mc.measure_sid  LEFT JOIN {{SCHEMA}}.duty_expression_descriptions ded ON ded.duty_expression_id = mc.duty_expression_id  LEFT JOIN {{SCHEMA}}.monetary_unit_descriptions mud ON mud.monetary_unit_code = mc.monetary_unit_code),measurement_unit_resources AS (  SELECT DISTINCT ON (mur.measurement_unit_code) mur.measurement_unit_code, mur.measure_sid, mur.component_position,    jsonb_build_object('id', mur.measurement_unit_code, 'type', 'measurement_unit') AS ref,    jsonb_build_object(      'id', mur.measurement_unit_code,      'type', 'measurement_unit',      'attributes', jsonb_build_object(        'description', mud.description,        'measurement_unit_code', mur.measurement_unit_code      )    ) AS resource  FROM (    SELECT positioned.measurement_unit_code, positioned.measure_sid, positioned.component_position, positioned.seq    FROM (      SELECT mc.measurement_unit_code, mc.measure_sid, row_number() OVER (PARTITION BY mc.measure_sid ORDER BY mc.measure_sid::text || '-' || mc.duty_expression_id) AS component_position, ms.seq      FROM {{SCHEMA}}.measure_components mc      JOIN measure_sequence ms ON ms.measure_sid = mc.measure_sid    ) positioned    WHERE positioned.measurement_unit_code IS NOT NULL 